<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\CommissionTier; use Illuminate\Http\Request;
class CommissionTierController extends Controller {private function authorize(Request $request):void{abort_unless($request->user()?->role==='superadmin',403,'Superadmin access required.');}public function index(Request $request){$this->authorize($request);return response()->json(['tiers'=>CommissionTier::orderBy('min_lifetime_sales')->get()]);}public function store(Request $request){$this->authorize($request);$data=$request->validate(['name'=>['required','string','max:80'],'min_lifetime_sales'=>['required','numeric','min:0','unique:commission_tiers,min_lifetime_sales'],'platform_fee_percent'=>['required','numeric','min:0','max:100'],'is_active'=>['boolean']]);$data['sort_order']=CommissionTier::max('sort_order')+1;return response()->json(['tier'=>CommissionTier::create($data)],201);}public function update(Request $request,CommissionTier $commissionTier){$this->authorize($request);$data=$request->validate(['name'=>['required','string','max:80'],'min_lifetime_sales'=>['required','numeric','min:0','unique:commission_tiers,min_lifetime_sales,'.$commissionTier->id],'platform_fee_percent'=>['required','numeric','min:0','max:100'],'is_active'=>['boolean']]);$commissionTier->update($data);return response()->json(['tier'=>$commissionTier->fresh()]);}}